package com.chronix.app;
import android.app.*;import android.content.*;import android.media.RingtoneManager;import android.os.Build;import androidx.core.app.NotificationCompat;
public class AlarmReceiver extends BroadcastReceiver {
 public static final String CHANNEL="chronix_alarm";
 @Override public void onReceive(Context c,Intent intent){createChannel(c);Intent open=new Intent(c,MainActivity.class).putExtra("openAlert",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent pi=PendingIntent.getActivity(c,7101,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new NotificationCompat.Builder(c,CHANNEL).setSmallIcon(com.chronix.app.R.drawable.chronix_icon).setContentTitle("Chronix · Alerta diaria").setContentText("Revisa cumpleaños, eventos y recordatorios próximos.").setStyle(new NotificationCompat.BigTextStyle().bigText("Abre Chronix para ver el resumen completo de cumpleaños, eventos y recordatorios dentro de tu rango configurado.")).setPriority(NotificationCompat.PRIORITY_HIGH).setCategory(NotificationCompat.CATEGORY_ALARM).setAutoCancel(true).setContentIntent(pi).build();((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(7100,n);if(intent.getBooleanExtra("weekly",false))AlarmScheduler.restore(c);}
 static void createChannel(Context c){if(Build.VERSION.SDK_INT>=26){NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);NotificationChannel ch=new NotificationChannel(CHANNEL,"Alarmas de Chronix",NotificationManager.IMPORTANCE_HIGH);ch.setDescription("Alertas diarias de Chronix");ch.setSound(RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM),null);nm.createNotificationChannel(ch);}}
}
